mapper.select:
SELECT
  eating_id, date, user_id, name, calories, protein, fat, carbo, created_at, updated_at
FROM eatings
WHERE user_id = #{userId}
  AND updated_at > #{updatedAt}
ORDER BY eating_id

mapper.update:
UPDATE eatings
SET date = #{date}, name = #{name}, calories = #{calories}, protein = #{protein}, fat = #{fat}, carbo = #{carbo}
WHERE eating_id = #{eatingId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM eatings
WHERE eating_id = #{eatingId}
  AND user_id = #{userId}
